def W(S, kind):
    l = [x for x in S.LINES if x[0] == kind][0]
    new = ', '.join(f"{e} ({op.upper()}{'' if sub == 'israel_people' else ' on ' + sub})" for e, op, sub in l[7]); re_ = '; '.join(f"{e} REUSED at {v.replace('Deut ', '')}{'' if sub == 'israel_people' else ' on ' + sub}" for e, v, sub in l[8])
    return f"ONE LINE {kind} ({l[5].upper()}, {l[2]}) writing {new}" + (f"; {re_}" if re_ else '')
